import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws_vals = vals.active
ws = wb.active

today_raw = ws_vals["I4"].value
if isinstance(today_raw, datetime):
    today = today_raw.date()
elif isinstance(today_raw, date):
    today = today_raw
else:
    today = datetime.strptime(str(today_raw)[:10], "%Y-%m-%d").date()

sales_by_date = {}
for row in ws_vals.iter_rows(min_row=2, max_row=ws_vals.max_row, min_col=1, max_col=2):
    a, b = row[0].value, row[1].value
    if a is None or b is None:
        continue

    if isinstance(a, datetime):
        d = a.date()
    elif isinstance(a, date):
        d = a
    else:
        try:
            d = datetime.strptime(str(a)[:10], "%Y-%m-%d").date()
        except ValueError:
            continue

    if isinstance(b, bool):
        continue
    try:
        v = float(b)
    except (TypeError, ValueError):
        continue

    sales_by_date[d] = sales_by_date.get(d, 0.0) + v

targets = []
d = today
while len(targets) < 4:
    if d.weekday() < 5:
        targets.append(d)
    d -= timedelta(days=1)

total = sum(sales_by_date.get(t, 0.0) for t in targets)
if isinstance(total, float) and total.is_integer():
    total = int(total)

ws["I6"] = total
wb.save(OUT)

print("today:", today.isoformat())
print("targets:", [t.isoformat() for t in targets])
print("total:", total)
