def to_date(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)):
        return (datetime(1899, 12, 30) + timedelta(days=float(value))).date()
    s = str(value).strip()
    if not s:
        return None
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            pass
    try:
        return datetime.fromisoformat(s[:10]).date()
    except Exception:
        return None

def workday_back(d, n):
    while n > 0:
        d -= timedelta(days=1)
        if d.weekday() < 5:
            n -= 1
    return d

i4 = to_date(vws["I4"].value)

if i4 is None:
    total = 0
    lower = None
else:
    anchor = i4
    if anchor.weekday() >= 5:
        anchor -= timedelta(days=1)
        while anchor.weekday() >= 5:
            anchor -= timedelta(days=1)

    lower = workday_back(anchor, 3)
    total = 0

    for row in range(2, vws.max_row + 1):
        a = vws.cell(row=row, column=1).value
        b = vws.cell(row=row, column=2).value
